from functools import lru_cache
from typing import Callable, Hashable, Iterable, List, TypeVar

Position = TypeVar("Position", bound=Hashable)


def make_value_fn(legal_moves: Callable[[Position], Iterable[Position]]
                  ) -> Callable[[Position], bool]:
    """W(p) is True iff some legal move leads to a losing position."""
    @lru_cache(maxsize=None)
    def W(p: Position) -> bool:
        return any(not W(q) for q in legal_moves(p))
    return W


def countdown_moves(n: int) -> List[int]:
    return list(range(n))


if __name__ == "__main__":
    W = make_value_fn(countdown_moves)
    print("n :", list(range(10)))
    print("W :", ["W" if W(n) else "L" for n in range(10)])
    assert all(W(n) == (n != 0) for n in range(50))
    print("Verified: countdown value W(n) <=> n != 0")

from functools import lru_cache
from typing import Callable, Hashable, Iterable, List, Tuple, TypeVar

Position = TypeVar("Position", bound=Hashable)


def make_value_fn(moves: Callable[[Position], Iterable[Position]]
                  ) -> Callable[[Position], bool]:
    @lru_cache(maxsize=None)
    def W(p: Position) -> bool:
        return any(not W(q) for q in moves(p))
    return W


def countdown_moves(n: int) -> List[int]:
    return list(range(n))


def sum_moves(moves: Callable[[Position], Iterable[Position]]):
    def m(pair: Tuple[Position, Position]):
        a, b = pair
        return [(a2, b) for a2 in moves(a)] + [(a, b2) for b2 in moves(b)]
    return m


if __name__ == "__main__":
    Wsum = make_value_fn(sum_moves(countdown_moves))
    # Flagship: a + a is always a loss for the mover.
    assert all(Wsum((a, a)) is False for a in range(30))
    print("Mirroring verified: Wsum((a,a)) is False for a in 0..29")
    # Two-heap Nim law: Wsum((m,n)) <=> m != n.
    assert all(Wsum((m, n)) == (m != n)
               for m in range(12) for n in range(12))
    print("Two-heap Nim law verified: Wsum((m,n)) <=> m != n")

from functools import lru_cache
from typing import Callable, Hashable, Iterable, List, TypeVar

Position = TypeVar("Position", bound=Hashable)


def make_value_fn(moves): 
    @lru_cache(maxsize=None)
    def W(p):
        return any(not W(q) for q in moves(p))
    return W


def optimal_move(moves, W, p):
    for q in moves(p):
        if not W(q):
            return q
    raise ValueError("not a winning position")


def countdown_moves(n: int) -> List[int]:
    return list(range(n))


def play_out(moves, W, start, opponent) -> int:
    """Return step index at which a terminal position is reached.
    Odd => opponent stuck (mover forced the win)."""
    p, step = start, 0
    while list(moves(p)):
        p = optimal_move(moves, W, p) if W(p) else opponent(p)
        step += 1
    return step


if __name__ == "__main__":
    W = make_value_fn(countdown_moves)
    opp = lambda p: countdown_moves(p)[0]  # greedy: move to 0
    for n in range(1, 15):
        step = play_out(countdown_moves, W, n, opp)
        assert (step % 2 == 1) == W(n)
    print("Determinacy verified: for winning n, mover forces the win (odd step).")

